private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null");
    }
    boolean result = false;
    if (this.size() != 0) {
        if (this.head == node) {
            this.head = node.next;
            if (this.head != null) {
                this.head.prev = null;
            }
            result = true;
        } else if (this.tail == node) {
            this.tail = node.prev;
            if (this.tail != null) {
                this.tail.next = null;
            }
            result = true;
        } else {
            ListNodeImpl<E> prev = node.prev;
            ListNodeImpl<E> next = node.next;
            prev.next = next;
            next.prev = prev;
            result = true;
        }
    }
    return result;
}

