public static List<ThreadSnapshot> loadThreadSnapshotsWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
        List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            List<ThreadSnapshot> threadSnapshotsForTimeRange = parseThreadSnapshots(file, timeRange);
            threadSnapshots.addAll(threadSnapshotsForTimeRange);
        }
        return threadSnapshots;
    }

    private static List<ThreadSnapshot> parseThreadSnapshots(File file, ProfileAnalyzeTimeRange timeRange) throws IOException {
        List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = br.readLine()) != null) {
                ThreadSnapshot threadSnapshot = parseThreadSnapshot(line);
                if (threadSnapshot != null && isInTimeRange(threadSnapshot, timeRange)) {
                    threadSnapshots.add(threadSnapshot);
                }
            }
        }
        return threadSnapshots;
    }

    private static ThreadSnapshot parseThreadSnapshot(String line) {
        String[] parts = line.split("\\s+");
        if (parts.length != 4) {
            return null;
        }
        ThreadSnapshot threadSnapshot = new ThreadSnapshot();
        threadSnapshot.setThreadId(Long.parseLong(parts[0]));
        threadSnapshot.setTimestamp(Long.parseLong(parts[1]));
        threadSnapshot.setExecutionTime(Long.parseLong(parts[2]));
        threadSnapshot.setExecutionId(Long.parseLong(parts[3]));
        return threadSnapshot;
    }

    private static boolean isInTimeRange(ThreadSnapshot threadSnapshot, ProfileAnalyzeTimeRange timeRange) {
        return (timeRange.getFromTime() <= threadSnapshot.getTimestamp()) && (threadSnapshot.getTimestamp() <= timeRange.getToTime());
    }
